package com.whaa.shop.catalog.application;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.whaa.shop.catalog.domain.Category;import com.whaa.shop.catalog.infrastructure.CategoryMapper;import com.whaa.shop.common.exception.BusinessException;import com.whaa.shop.product.domain.Product;import com.whaa.shop.product.infrastructure.ProductMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.List;
@Service public class CategoryService {private final CategoryMapper categories;private final ProductMapper products;public CategoryService(CategoryMapper c,ProductMapper p){categories=c;products=p;}public List<Category> list(boolean enabledOnly){return categories.selectList(new LambdaQueryWrapper<Category>().eq(enabledOnly,Category::getEnabled,true).orderByAsc(Category::getSortOrder));}
 @Transactional public Category save(Category c){if(c.getName()==null||c.getName().isBlank())throw new BusinessException("分类名称不能为空");if(c.getSortOrder()==null)c.setSortOrder(0);if(c.getEnabled()==null)c.setEnabled(true);if(c.getParentId()!=null&&categories.selectById(c.getParentId())==null)throw new BusinessException("父分类不存在");if(c.getId()==null)categories.insert(c);else categories.updateById(c);return c;}
 @Transactional public void delete(Long id){if(categories.selectCount(new LambdaQueryWrapper<Category>().eq(Category::getParentId,id))>0)throw new BusinessException("请先删除子分类");if(products.selectCount(new LambdaQueryWrapper<Product>().eq(Product::getCategoryId,id))>0)throw new BusinessException("分类下存在商品，不能删除");categories.deleteById(id);}}
